namespace TKR.WorldServer.logic{public partial class BehaviorDb{
    private _ StudioIndexFixture=()=>Behav().Init("Cave Pirate Brawler",new State("motion",StudioIndexWrap(new StudioIndexChildren(){ [7]=new Shoot(20,count:4,fixedAngle:0,coolDown:100),/* index note */[2]=new Shoot(20,count:6,fixedAngle:0,coolDown:100) })));
    static Prioritize StudioIndexWrap(StudioIndexChildren children)=>new Prioritize(System.Linq.Enumerable.ToArray(children));
    sealed class StudioIndexChildren:System.Collections.Generic.IEnumerable<CycleBehavior>{
        readonly System.Collections.Generic.SortedDictionary<int,CycleBehavior> values=new();
        public CycleBehavior this[int key]{get=>values[key];set=>values[key]=value;}
        public System.Collections.Generic.IEnumerator<CycleBehavior> GetEnumerator()=>values.Values.GetEnumerator();
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()=>GetEnumerator();
    }
}}
""";
var doc=new BehaviorDocument(source,adapter,sourceFile:file);var list=doc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&doc.Expression(n).StartsWith("new StudioIndexChildren"));var first=list.Children[0];var second=list.Children[1];var ids=doc.Identities;
Check(!list.ArgumentRequiresSource&&first.Kind=="InitializerEntry"&&first.Parameters.Single().Name=="key"&&first.Children.Single().Kind=="Shoot","Indexed native assignments expose their actual scalar key and setter value child");
doc.Apply(new(doc.Revision,"Change index",[new(first.Id,"key","1")]),d=>adapter.Validate(d,entity));Check(doc.Find(first.Id).Parameters.Single().Expression=="1"&&doc.Find(second.Id).Children.Single().Id==second.Children.Single().Id,"Native index edits preserve neighboring identities");
var replacement=doc.ReplaceChild(first.Id,"new Shoot(20,count:8,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,entity));Check(doc.Find(replacement).Kind=="Shoot"&&doc.Expression(doc.Find(first.Id)).StartsWith("[1]"),"Typed setter value replacement preserves indexed syntax and key");
doc.MoveNode(second.Id,-1,d=>adapter.Validate(d,entity));Check(doc.Find(list.Id).Children.First().Id==second.Id&&doc.Source.Contains("/* index note */"),"Source reorder retains indexed entry syntax, comments and identity");
var duplicate=doc.DuplicateNode(first.Id,d=>adapter.Validate(d,entity));Check(duplicate!=first.Id&&doc.Find(duplicate).Children.Single().Id!=replacement,"Indexed entry duplication creates an independent source pair and descendant");doc.Undo();
var accepted=doc.Source;Reject(()=>doc.ReplaceChild(first.Id,"new TKR.WorldServer.logic.transitions.TimedTransition(100,\"motion\")"),"Setter child conversion rejects incompatible native types");Check(doc.Source==accepted,"Rejected indexed edits preserve source and history");
var project=new StudioProject{SourceFile=file,Source=doc.Source,EntityId=entity,Identities=doc.Identities,Player=new(Invulnerable:true)};await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project)){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{8,6}),"Original indexer setter and sorted enumeration determine native runtime attack order");}
while(doc.Source!=source)if(!doc.Undo())throw new Exception("Missing index history");Check(doc.Identities.SequenceEqual(ids),"Complete indexed editing history restores original source and identities");
var contract=doc.EntryOverloads(list.Id).Single();Check(contract.IsIndexer&&contract.Metadata.Parameters.Select(p=>p.Name).SequenceEqual(new[]{"key","value"}),"Indexed creation discovers actual key/value setter parameters");var made=doc.CreateCollectionEntry(list.Id,contract.Signature,new Dictionary<string,string>{{"key","3"}},new Dictionary<string,string>{{"value","new Shoot(20,count:9,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,entity));Check(doc.Find(made).Kind=="InitializerEntry"&&doc.Expression(doc.Find(made)).StartsWith("[3]"),"Selected indexer contract creates a complete indexed assignment in one revision");var copied=doc.CopyNodes([first.Id]);var pasted=doc.PasteNodes(list.Id,1,copied,d=>adapter.Validate(d,entity)).Single();Check(pasted!=first.Id&&doc.Find(pasted).Children.Single().Id!=first.Children.Single().Id,"Whole indexed entry clipboard import retains setter binding with independent descendants");doc.Undo();var next=doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","5"}},new Dictionary<string,string>{{"value","new Shoot(20,count:7,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,entity));Check(doc.Find(next).Kind=="InitializerEntry"&&doc.Expression(doc.Find(next)).StartsWith("[5]"),"Prototype creation edits the complete indexed key/value pair without converting to Add syntax");
var dictionarySource=source.Replace("StudioIndexWrap(new StudioIndexChildren()", "StudioIndexWrap(new System.Collections.Generic.Dictionary<int,CycleBehavior>()").Replace("static Prioritize StudioIndexWrap(StudioIndexChildren children)=>new Prioritize(System.Linq.Enumerable.ToArray(children))","static Prioritize StudioIndexWrap(System.Collections.Generic.Dictionary<int,CycleBehavior> children)=>new Prioritize(System.Linq.Enumerable.ToArray(children.Values))");var dictionary=new BehaviorDocument(dictionarySource,adapter,sourceFile:file);var dictionaryList=dictionary.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&dictionary.Expression(n).StartsWith("new System.Collections.Generic.Dictionary"));Check(dictionaryList.Children.All(n=>n.Kind=="InitializerEntry")&&!dictionaryList.ArgumentRequiresSource,"A standard native-value Dictionary exposes compiler-bound indexed child entries");var dictionaryContract=dictionary.EntryOverloads(dictionaryList.Id).Single();dictionary.CreateCollectionEntry(dictionaryList.Id,dictionaryContract.Signature,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>{{"value","new Shoot(20,count:8,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,entity));await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=dictionary.Source,Identities=dictionary.Identities})){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{4,6,8}),"Original Dictionary setters and value enumeration retain source insertion order");}
var overloadSource=source.Replace("public CycleBehavior this[int key]{get=>values[key];set=>values[key]=value;}","public CycleBehavior this[int key]{get=>values[key];set=>values[key]=value;} public CycleBehavior this[string key]{get=>values[key.Length];set=>values[key.Length]=value;}");var overloadDoc=new BehaviorDocument(overloadSource,adapter,sourceFile:file);var overloadList=overloadDoc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&overloadDoc.Expression(n).StartsWith("new StudioIndexChildren"));var intContract=overloadDoc.EntryOverloads(overloadList.Id).Single(c=>c.Metadata.Parameters[0].Type=="Int32");var unchanged=overloadDoc.Source;Reject(()=>overloadDoc.CreateCollectionEntry(overloadList.Id,intContract.Signature,new Dictionary<string,string>{{"key","\"different\""}},new Dictionary<string,string>{{"value","new Shoot(20)"}}),"Indexer creation rejects a key that selects a different setter overload");Check(overloadDoc.Source==unchanged,"Rejected setter rebinding preserves the accepted initializer");overloadDoc.LockedNodes.Add(overloadList.Id);Reject(()=>overloadDoc.CreateCollectionEntry(overloadList.Id,intContract.Signature,new Dictionary<string,string>{{"key","3"}},new Dictionary<string,string>{{"value","new Shoot(20)"}}),"Indexed collection locks protect complete key/value creation");
var multiSource=source.Replace("[7]=","[7,1]=").Replace("[2]=","[2,1]=").Replace("this[int key]{get=>values[key];set=>values[key]=value;}","this[int key,int band]{get=>values[key+band];set=>values[key+band]=value;}");var multi=new BehaviorDocument(multiSource,adapter,sourceFile:file);var multiList=multi.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&multi.Expression(n).StartsWith("new StudioIndexChildren"));Check(multiList.Children[0].Parameters.Select(p=>p.Name).SequenceEqual(new[]{"key","band"}),"Multi-key indexers expose each compiler-bound scalar input in order");var multiContract=multi.EntryOverloads(multiList.Id).Single();var multiMade=multi.CreateCollectionEntry(multiList.Id,multiContract.Signature,new Dictionary<string,string>{{"key","9"},{"band","2"}},new Dictionary<string,string>{{"value","new Shoot(20,count:7,fixedAngle:0,coolDown:100)"}},d=>adapter.Validate(d,entity));Check(multi.Expression(multi.Find(multiMade)).StartsWith("[9, 2]"),"Multi-key creation retains native index argument order and setter value");
var path=Path.GetFullPath(".artifacts/indexed-entry.rbs");BehaviorDocument.Save(path,project with{Source=doc.Source,Identities=doc.Identities});var reopened=BehaviorDocument.Load(path);Check(new BehaviorDocument(reopened.Source,adapter,reopened.Identities,file).Identities.SequenceEqual(doc.Identities),"Indexed entry and descendant identities survive save/reopen");
var arraySource=source.Replace("[7]=new Shoot(20,count:4,fixedAngle:0,coolDown:100)","[7]=new CycleBehavior[]{new Shoot(20,count:4,fixedAngle:0,coolDown:100),new Shoot(20,count:2,fixedAngle:0,coolDown:100)}").Replace("[2]=new Shoot(20,count:6,fixedAngle:0,coolDown:100)","[2]=new CycleBehavior[]{new Shoot(20,count:6,fixedAngle:0,coolDown:100)}").Replace("SortedDictionary<int,CycleBehavior>","SortedDictionary<int,CycleBehavior[]>").Replace("public CycleBehavior this[int key]","public CycleBehavior[] this[int key]").Replace("=>values.Values.GetEnumerator()","=>System.Linq.Enumerable.SelectMany(values.Values,v=>v).GetEnumerator()");var arrays=new BehaviorDocument(arraySource,adapter,sourceFile:file);var arrayList=arrays.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&arrays.Expression(n).StartsWith("new StudioIndexChildren"));var arrayEntry=arrayList.Children[0];var values=arrayEntry.Children.Single();Check(values.Argument is{IsArray:true}&&values.Children.Count==2,"Indexed collection values expose their actual native array input owner");arrays.MoveNode(values.Children[1].Id,-1,d=>adapter.Validate(d,entity));Check(arrays.Find(values.Id).Children.First().Id==values.Children[1].Id,"Value-list reorder retains the indexed key and exact element identities");var arrayNew=arrays.CreateInitializerEntry(arrayEntry.Id,new Dictionary<string,string>{{"key","3"}},new Dictionary<string,string>{{"value","new CycleBehavior[]{new Shoot(20,count:8,fixedAngle:0,coolDown:100)}"}},d=>adapter.Validate(d,entity));Check(arrays.Find(arrayNew).Children.Single().Children.Count==1&&arrays.Expression(arrays.Find(arrayNew)).StartsWith("[3]"),"Complete indexed entry creation replaces a native value array without changing setter binding");await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=arrays.Source,Identities=arrays.Identities})){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{6,8,2,4}),"Actual indexed array setters and flattened sorted enumeration determine native attack order");}
var namedSource=multiSource.Replace("[7,1]","[band:1,key:7]");var named=new BehaviorDocument(namedSource,adapter,sourceFile:file);var namedEntry=named.Entities.Single().Root.Descendants().First(n=>n.Kind=="InitializerEntry");Check(namedEntry.Parameters.Select(p=>p.Name).SequenceEqual(new[]{"band","key"}),"Named reordered index arguments retain actual scalar binding rather than positional guesses");
